  Mail_120909_Desc = {
    Text = "Kính gửi Người giữ gìn:\n        Trong cập nhật V2.4.0, chúng tôi đã nâng cao phần thưởng cho \"Đóng góp nguồn nguyên liệu - Quỹ đóng góp cựu sinh viên\". Đối với những người giữ gìn đã nhận hết phần thưởng trước khi cập nhật, chúng tôi sẽ chuyển lại phần thưởng tương ứng. Xin vui lòng kiểm tra."
