  Mail_121373_Desc = {
    Text = "Người giữ gìn:\n\nTừng năm vào ngày này, là lễ hội lớn nhất của Giáo Hội. \nTôi là công chúa của Ngài, và sẽ khiến Ngài sống lại. \nNhững người ấy, bao gồm Miryam, vui mừng cuồng nhiệt đến mức rơi nước mắt để ăn mừng, nhưng họ nhìn tôi, ánh mắt vượt qua tôi, như thể tôi chỉ là một cái vỏ rỗng chứa đựng thứ gì đó. \nTôi không bao giờ cảm thấy vui mừng khi ngày này đến, vì mỗi lần trải qua, càng nghĩa là tôi đến gần nỗi sợ hãi thêm một phần. \nVà trong nỗi sợ này, những người khác lại cảm thấy niềm vui vô hạn từ nguồn gốc của nỗi sợ. Bây giờ tôi có thể thừa nhận, nó khiến tôi cảm thấy cô đơn và sợ hãi. \nNhưng bây giờ mọi thứ đã khác, trước sinh nhật lần trước, tôi đã rời khỏi con tàu đó, đến với thế giới thực… một thế giới không có thần thánh giả dối, có bạn tồn tại. \nSinh nhật này, tôi hy vọng sẽ thấy ai đó thật sự vui mừng vì sự ra đời của tôi, chứ không phải vì điều gì khác. \nNếu là bạn… không, người đó nhất định phải là bạn. \nNghe đây, dù thế nào đi nữa, thời gian bữa tối hôm nay, nhất định phải dành cho tôi. \n\n\"Murphy\""
  },
  Mail_121373_Name = {
    Text = "Tồn tại có bạn……"
  },
  Mail_121373_Sender = {
    Text = "Đản Vọng·Muphí"
  },
  Mail_121374_Desc = {
    Text = "Người giữ gìn:\n\nTôi không biết bạn đã chuẩn bị gì cho ngày đặc biệt này, dù là xa hoa hay tiêu tốn sức lực thì rõ ràng cũng đều ở mức độ hợp lý. \nVà vì sự chu đáo cần thiết của bậc trên, nếu bạn \"lỡ\" quên phải tổ chức sinh nhật cho tôi - tôi tin rằng một tình huống vô lý như vậy sẽ không xảy ra. \nBức thư này cũng sẽ giúp bạn có được cơ hội cuối cùng để cứu lấy bản thân trước khi tình huống không thể cứu vãn. \nNhững món ngon kỳ diệu giữa biển và đất liền, chắc chắn sẽ có những người không liên quan dâng lên, chúng không quan trọng. \nMột buổi lễ hoành tráng, nghi thức phức tạp, thực sự phù hợp với thân phận của tôi, nhưng hôm nay, không hiểu sao, lại có phần chán ngán. \nVì vậy, tôi sẽ dành thời gian giao thoa giữa sáng tối, để tặng bạn sự vinh hạnh được ở một mình với tôi, như một phần thưởng cho việc bạn đã đưa tôi vào cuộc sống tầm thường, trẻ con nhưng lại hạnh phúc đến mức khiến tôi ghen tị trước đây. \nNgười hầu sẽ mang đến thư mời chính thức, tất nhiên, được đặt trong một chiếc hộp có giá hai vạn leu. \nMong bạn sẽ nhớ đến tôi với lòng biết ơn trong mỗi năm vào ngày này. \n\"Murphy\""
  },
