  Mail_122522_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n Hoạt động \"Bóng tối của thị trấn mưa·klon\"đã kết thúc, hiện tại sẽ chuyển đổi \"Skull của thú nhợt nhạt\",\"Đầu lâu thú bóng\" và\"Xương đầu thú vật màu đỏ thẫm\" còn lại của Người Giữ Gìn theo tỷ lệ mỗi cái đổi lấy \"Vé hoa hồng vàng\" × 40, xin hãy nhớ kiểm tra."
