  Mail_122567_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n Hoạt động \"Lễ tế hỏa trong vùng sương mù\"đã kết thúc, hiện tại sẽ chuyển đổi số lượng còn lại của Người Giữ Gìn là \"tầm nhìn của sương mù\", \"Giấc mơ của sương mù\", \"nguồn của sương mù\" theo tỷ lệ mỗi cái đổi lấy \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn nhớ kiểm tra."
