  Mail_131767_Desc = {
    Text = "Ta @2! @3 là @2 tối cao @3 hỗn @4 và hủy @2! Hô to @4…! \n\n Ôi trời ơi! Hãy xem bạn đã làm gì!!! Bạn đã chạm vào điều cấm kỵ của thần linh tối cao! Giờ thì tốt rồi, lời thì thầm của Ngài đã vang vọng khắp thế giới của bạn, thảm họa đen tối sẽ bắt đầu lây lan từ thiết bị liên lạc của bạn, nuốt chửng mọi thứ xung quanh bạn… \n Tội nghiệp nhỏ, sự liều lĩnh của bạn thực sự khiến tôi khó xử. Nhưng cũng đừng quá tuyệt vọng, trong cái rủi có cái may, bạn đã gặp tôi — tiên nữ vĩ đại của giáo phái, người được thần linh chọn, người thực hiện của thần tối cao, người thừa kế hợp pháp của giáo phái vĩ đại, người cứu rỗi nỗi khổ đau, bạn thân của thần vương! Tôi là ý chí của thần thiện và tình yêu, không thể chịu đựng nỗi khổ đau trên thế gian này, tôi sẽ dùng sức mạnh tối cao của mình, cứu rỗi mỗi một kẻ tinh nghịch ngu ngốc. \n Ôi, tiên nữ thấy ánh mắt chế nhạo của bạn. Không sao cả, thần thiện yêu thương nhân loại, không bao giờ bận tâm đến sự ngu dốt của nhân loại. Sự không tin tưởng vào đấng cứu thế là con đường mà mỗi tín đồ phải trải qua. Những món quà này, chính là ân thưởng của người thực hiện thần linh dành cho bạn. \n Bây giờ, con đường sáng đã chỉ dẫn cho bạn: hãy mang theo sự chân thành của bạn, đến nhà thờ @2 ở thành phố @3, dâng lên thần thiện lòng trung thành của bạn, bạn sẽ nhận được sức mạnh mà bạn mơ ước, giải thoát khỏi lời nguyền của cơn ác mộng. Tất nhiên, cần phải dâng lên cả tài sản của bạn. Xin đừng hiểu lầm, thần thiện không bao giờ quan tâm đến sự hồi báo của thế gian, nhưng các tín đồ của Ngài cũng cần phải chi tiền để làm việc. Đừng keo kiệt với những thứ tầm thường này, tín đồ thân mến, một đồng một mớ. \n Hô lớn danh hiệu của thần thiện, chờ đợi thời khắc kỳ tích xuất hiện! \n\n Tiên nữ vĩ đại của giáo phái, người được thần linh chọn"
  },
  Mail_131767_Name = {
    Text = "Xin đừng chạm vào @2 này"
  },
