  Mail_133703_Desc = {
    Text = "Kính gửi Người Giữ Bí Mật:\nPhiên bản {s1} đã kết thúc, hệ thống đã tự động chuyển đổi số\"Lõi Hư Ảo\" còn lại của Người Giữ Bí Mật theo tỷ lệ mỗi 1 cái đổi thành \"Lõi Thuần Khiết\" × 1. Lần này đã chuyển đổi tổng cộng \"Lõi Thuần Khiết\" × {s2}, xin Người Giữ Bí Mật nhớ kiểm tra."
