  Mail_134024_Desc = {
    Text = "Kính gửi Người Giữ Bí Mật:\n \"Thử Luyện Hàng Ngày\"đã bị gỡ bỏ, số\"Chứng Nhận Đại Diện\" còn lại của Người Giữ Bí Mật sẽ được quy đổi theo tỷ lệ mỗi chiếc đổi được \"Phiếu Vàng Tường Vi\" × 10000, xin Người Giữ Bí Mật nhớ kiểm tra."
