  Mail_134024_Name = {
    Text = "Thu hồi Chứng Nhận Đại Diện"
  },
  Mail_134024_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_134067_Desc = {
    Text = "Người Giữ Bí Mật:\n\nHôm nay có chuyện đặc biệt muốn bàn với cậu.\nTớ muốn đi dạo bừa trên phố, cứ thế bình thường ngắm nhìn đủ thứ hay ho, tùy hứng đi đây đi đó, trải qua một ngày bình thường.\n\nRồi tớ đã đi hỏi phòng giáo vụ. Kết quả họ nói, vì lý do an toàn, chỉ được phép ra khỏi trường khi có cậu đi cùng.\nCòn dặn đừng làm người khác sợ, cũng đừng ra ngoài rồi cái gì cũng nhét vào miệng. Thật là thất lễ.\nMà, chuyện là vậy đó, tóm lại có thể ra ngoài đi dạo không? Mọi người cùng đi nhé.\n\n... Không hiểu sao lại nghĩ đến, hạt bồ công anh ấy mà,\ntổng có một ngày sẽ cưỡi gió, lên đường đến vùng đất định mệnh của mình,\ncó lẽ là ngày mai, có lẽ là chuyện rất lâu rất lâu sau này.\nNghĩ đi nghĩ lại, thấy nhân lúc bây giờ cùng mọi người làm thêm nhiều việc, hình như cũng không tệ nhỉ.\n\nTóm lại, tớ đợi cậu trước ký túc xá. Nhờ cậu nhé！\n\nSaya"
  },
  Mail_134067_Name = {
    Text = "Dạo phố…"
  },
  Mail_134067_Sender = {Text = "Saya"},
  Mail_134068_Desc = {
    Text = "Người giữ bí mật:\n\nTôi cảm thấy, hôm nay là một ngày đặc biệt. Nhưng đường viền của ký ức, vẫn mờ nhạt như thế.\nDuy chỉ có cái tên \"Saya\" này, miễn cưỡng giữ tôi ở lại nơi đây.\n\nCảm giác đó không phải cô đơn, cũng không phải buồn bã, không phải thứ cảm xúc rõ ràng như vậy.\nNếu nhất định phải đặt tên cho tâm trạng này…… có lẽ, sẽ là \"khoảng trống\" nhỉ.\nKhông có gì cả, trong vắt vô tận, khoảng thời gian tĩnh lặng.\n\nNếu có một ngày, những hạt giống bồ công anh bay theo gió,\nỞ mọi góc của thế giới này, chỉ trắng tinh, lặng lẽ rơi xuống……\nKhi đó, có lẽ tôi cuối cùng cũng có thể cảm thấy, thế giới này là \"đặc biệt\".\n\nKhi đó, màn sương xám bao phủ Londinium, áng mây đỏ rực cháy lúc hoàng hôn, và bầu trời mà cậu luôn ngước nhìn ở quảng trường trường học, tất cả sẽ được bồ công anh phủ kín, biến thành màu trắng tinh khôi. Biến thành màu thuộc về tôi.\n\nVì vậy…… nếu, cậu muốn trao cho tôi điều gì đó.\nThứ đó không cần phải là quà tặng, chỉ cần một đoạn \"ký ức\" là được.\n\nTôi, trong thế giới trắng tinh nơi bồ công anh nở rộ,\nchỉ lặng lẽ, chờ đợi khoảnh khắc đó đến.\n\nKhi một ngày nào đó cậu lại ngước nhìn bầu trời ở quảng trường Misagre,\nxin hãy để sợi lông tơ trắng lướt qua rìa tầm mắt,\nhòa chồng lên hình bóng của tôi - người đã từng trò chuyện cùng cậu, dù chỉ một chút thôi.\n\nSaya"
  },
  Mail_134068_Name = {
    Text = "Lời hẹn ước của bồ công anh…"
  },
  Mail_134068_Sender = {Text = "Saya"},
  Mail_139809_Desc = {
    Text = "Kính gửi Người Giữ Bí Mật:\n        Cảm ơn bạn đã ủng hộ và công nhận《Đêm Trước Lãng Quên》. Để mang lại trải nghiệm chơi game tốt hơn cho các Người Giữ Bí Mật tại Đại học Misage, chúng tôi trân trọng mời bạn điền vào bảng khảo sát trải nghiệm dưới đây. Để cảm ơn sự hợp tác của bạn, chúng tôi đã chuẩn bị「Lõi Bạc」× 200 làm phần thưởng, hoàn thành bảng khảo sát là có thể nhận ngay. Thời hạn điền khảo sát là 9:00 ngày 16 tháng 5, vui lòng chú ý điền đúng hạn.\n        <SurveyLink:【Nhấn để đến điền khảo sát】>\n        Chúng tôi sẽ lắng nghe nghiêm túc ý kiến của từng Người Giữ Bí Mật, phản hồi của bạn chắc chắn sẽ giúp Đại học Misage ngày càng tốt hơn!\n        ——Nguyện chìa khóa bạc dẫn lối phía trước."
