  Mail_141507_Desc = {
    Text = "Người giữ bí mật: \n\nNgày sinh, có lẽ đây là một ngày quan trọng đối với bạn? \nĐối với tôi, trọng lượng của mỗi ngày trên mạng lưới số phận đều là như nhau. Chính những câu chuyện khác đã mang lại ý nghĩa đặc biệt cho ngày này. \nTôi được sinh ra vào ngày này, hiểu được lời tiên tri vào ngày này, nhận được bánh xe dệt số phận vào ngày này, và nhìn thấy những sợi chỉ số phận phức tạp, cùng với những cơn ác mộng ở đầu sợi chỉ. \nĐối với người dệt số phận, ngày này thật tầm thường. Đối với diễn viên trên sân khấu, ngày này đáng để ăn mừng. Và trong tất cả các danh tính, điều khiến tôi vui vẻ nhất là chính mình với tư cách là một diễn viên. \nNgười giữ bí mật, hôm nay, ánh sáng của nhà hát số phận đã tắt, chỉ còn lại một sân khấu rực rỡ. Bạn đã từng đề cập rằng, muốn thấy nhiều hơn về số phận mà tôi đã trải qua. Và bây giờ, sân khấu này sẽ diễn một đoạn câu chuyện về chính tôi. \nTôi không biết đoạn nào sẽ được diễn. Tôi sẽ đưa những hồi ức lên sân khấu, và trong những khoảnh khắc mạnh mẽ đó, cô ấy sẽ chọn một đoạn mà bạn mong chờ nhất, để trình diễn trên sân khấu đêm nay. \nCâu chuyện đó có thể khiến tôi đau đớn, có thể khiến tôi khó xử, nhưng điều đó không quan trọng, phải không? Tôi nghĩ, đôi khi để bánh xe tự dệt nên, làm một khán giả thuần túy, là một điều thú vị. \nVé vào cửa duy nhất cho buổi biểu diễn này, hiện đã ở trong tay bạn. Hãy đến với bức thư này, Người Giữ Gìn. Tối nay, một câu chuyện không ai khác biết, đang chờ đợi bạn đến. \n\nArachne"
  },
  Mail_141507_Name = {
    Text = "Câu chuyện ẩn"
  },
  Mail_141507_Sender = {Text = "Arachne"},
  Mail_141833_Desc = {
