  Mail_148514_Desc = {
    Text = "Kính gửi người giữ bí mật:\n        Trong bản cập nhật phiên bản V1.4.3.5, chúng tôi đã thêm màn chơi \"Vua mới\" vào \"Thế giới Mộng Ảo: Xâm phạm\". Do một số người giữ bí mật không kịp thời biết đến nội dung cập nhật này, đã nhầm tưởng rằng \"Thế giới Mộng Ảo: Xâm phạm\" đã hoàn thành toàn bộ.\n        Vì vậy, trong bản cập nhật phiên bản V2.6.2 lần này, chúng tôi đã bổ sung tiến độ hoàn thành màn chơi \"Vua mới\" cho những người giữ bí mật đã hoàn thành các màn chơi tiếp theo sau \"Vua mới\" trước khi cập nhật, đồng thời bổ sung phần thưởng thông quan lần đầu tương ứng, kính mong bạn kiểm tra nhận thưởng."
  },
  Mail_148514_Name = {
    Text = "Bổ sung tiến độ \"Xâm phạm\""
  },
  Mail_148514_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_148515_Desc = {
    Text = "Người giữ bí mật thân mến:\n\nTa-da~ Có bất ngờ không nào? Đây là sinh nhật đầu tiên của tiên nữ này tại Misaque, vì vậy——\nThật bất ngờ! Không có bất kỳ email khuyến mãi, lời mời lễ bái, thậm chí cả lời tiên tri ngày tận thế cũng không có~\nNhưng đừng thất vọng, tiên nữ này tất nhiên đã chuẩn bị một số phúc lợi quý giá hơn, tốt hơn cho những tín đồ đặc biệt nhất rồi.\nLà tiên nữ giáo mẫu Toàn tri toàn năng, tất nhiên có thể dự liệu được những nghi ngờ và đề phòng hiển nhiên đó, dù điều đó khiến tiên nữ này cảm thấy đôi chút buồn lòng, nhưng, để phổ rộng ân huệ của giáo phái, những Hy sinh nhỏ nhoi luôn là điều không thể tránh khỏi.\nVì vậy, hãy suy nghĩ thật kỹ rồi thử xem sao, dù sao cũng chẳng mất gì, lỡ là thật thì sao? Đúng không?\nĐây là cơ hội chỉ có một lần trong năm, dù thế nào cũng không nên bỏ lỡ đấy~\nKhông cần bất kỳ Cúng Tế nào, cũng không cần bất kỳ lời hứa hay trao đổi nào, chỉ cần cùng tiên nữ giáo mẫu thưởng thức một buổi trà chiều ngọt ngào, bạn sẽ biết được bên dưới lớp băng tuyết, rốt cuộc ẩn chứa bao nhiêu tình cảm chân thành dành cho bạn.\nChẳng phải đây là một đề nghị đầy hấp dẫn sao?\nGhi chú: Vui lòng nhớ mang theo ít nhất 10, 100, 1000 Léofang đủ để thanh toán, càng nhiều càng tốt.\n\nđợi bạn tại quán mà chúng ta đều biết\nCarabao"
  },
  Mail_148515_Name = {
    Text = "☆☆☆Email Phúc Lợi Siêu Khủng☆☆☆"
  },
  Mail_148515_Sender = {Text = "Caraboo"},
  Mail_149949_Desc = {
    Text = "Bức thư này đã lưu chuyển ngàn lần giữa hai cõi âm dương, tuyệt đối chớ xóa!\n\nRằm tháng Bảy, cửa quỷ mở, gió âm nổi, hồn ma về.\nTa là ■■■ thành Hộ thuộc Quốc gia Bàn Long, một tờ giấy xấu xí là vậy!\nPhụng chiếu lệnh Trung Nguyên, mang phù triệu hồn, đêm nay giáng chú tại đây. Người thấy chữ này, hồn sẽ vào sổ, tên đã ghi bộ, nếu không chuyển cho năm mươi người cõi dương trước giờ Tý, tất sẽ——\nVăn bản hỏng ngay trước khi lưu trữ……\nTrà sữa trân châu mãi thiếu ba viên……\nThiết bị liên lạc bạc tâm pin mãi kẹt ở 1%, sạc mãi không đầy……\n\nCứ ngoan ngoãn làm theo, chú tự giải, phù tự thiêu, ác quỷ không quấy, đèn cũng sáng mãi.\nChuyển tiếp!! Ngay lập tức!!!"
  },
  Mail_149949_Name = {
    Text = "[Cảnh Báo Trung Nguyên] Kẻ nào dám xóa thư này, tất sẽ bị……"
  },
  Mail_149949_Sender = {
    Text = "Nhất Chỉ Yểm"
  },
  Mail_149985_Desc = {
    Text = "Chủ quân:\n\nĐột ngột gửi thư, mong rằng điều này không khiến ngài cảm thấy bất tiện. Nhưng có những tâm sự, chỉ có thể thổ lộ với ngài mà thôi.\nĐêm qua, tôi đã có một giấc mơ sau bao lâu xa cách, trong mơ, tôi trở về ngôi nhà xưa. Tất cả đều thân thuộc đến vậy, bàn tay ấm áp rộng lượng của cha, khúc dân ca mà người hầu gái khe khẽ hát khi Quét dọn, và chú ngựa lùn màu trắng thuộc về tôi......Tôi cứ tưởng, chúng đã bị tôi bỏ lại trong vũng lầy ký ức, gặp lại trong mơ, vẫn ấm áp như vậy.\nSau khi tỉnh dậy, tôi nhìn thấy thầy trò Misaque ngoài cửa sổ đang trò chuyện thong thả đi qua, yên bình và tươi đẹp đến vậy, khiến tôi bỗng cảm thấy, khung cảnh này chẳng khác gì trong mơ. Đồng thời, tôi cũng nhận ra rằng, thứ vô hình bám trên người tôi, từ sáng nay đã rất yên tĩnh. Chẳng lẽ, vào ngày sinh nhật thực sự sẽ gặp được những điều may mắn sao.\nNếu quả thực như vậy, có lẽ, hôm nay tôi cũng có thể tham lam một lần......\nTôi biết người ta thường thích ước nguyện vào ngày sinh nhật, như một kỳ vọng cho cả năm. Tôi đã từ lâu không dám mong được ai chúc mừng sinh nhật, nhưng quả thực có một cơ hội tôi muốn có được.\nCũng như ngài đã trao sự tin tưởng cho tôi, tôi cũng sẽ không Giữ lại bất cứ điều gì với ngài, vì vậy, xin hãy cho phép tôi bày tỏ điều ước với ngài:\nNếu lần sau chủ quân có sắp xếp nhiệm vụ, xin hãy bổ nhiệm tôi làm Vệ sĩ, cùng đồng hành với ngài.\nDù thế nào đi nữa, tôi mong rằng vào lúc ngài cần giúp đỡ nhất, tôi luôn có thể đứng trước mặt ngài trong tức khắc, trở thành lá chắn vững chắc nhất của ngài.\nĐây chính là tâm nguyện tôi đã ước cho năm nay.\n\nOrci"
  },
  Mail_149985_Name = {
    Text = "Điều ước sinh nhật…"
  },
  Mail_149985_Sender = {
    Text = "Bội Thệ·Orci"
  },
  Mail_18019_Desc = {
    Text = "Thân gửi Người Giữ Gìn: \n Hệ thống đã phát hiện tài khoản hiện tại đã thực hiện một hành vi hoàn tiền. Nhóm phát triển đã khấu trừ tại {s1} phần tiền ảo tương ứng với đơn hàng hoàn tiền của bạn. Nếu số dư tiền ảo sau khi khấu trừ bị âm, cần khôi phục về số dương để sử dụng bình thường. \n Nếu có bất kỳ thắc mắc nào, vui lòng liên hệ với bộ phận hỗ trợ khách hàng."
  },
  Mail_18019_Name = {
    Text = "Thông tin xử lý hoàn tiền"
  },
  Mail_18019_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_18020_Desc = {
    Text = "Xin chào, Người Giữ Gìn, phần thưởng nhận được trong {s1} đã được gửi đến bạn qua đính kèm email do ba lô của bạn đã đầy. Vui lòng dọn dẹp ba lô và nhận phần thưởng kịp thời"
  },
  Mail_18020_Name = {
    Text = "Phần thưởng chưa nhận sẽ được phát lại"
  },
  Mail_18020_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_18021_Desc = {
    Text = "Thân gửi Người Giữ Bí Mật:\nHoạt động Đề Tài Học Kỳ kỳ này sẽ kết thúc vào {s1}[GMT+8]. Sau khi hoạt động kết thúc, bạn sẽ không thể nhận phần thưởng liên quan đến Đề Tài Học Kỳ kỳ này. Xin Người Giữ Bí Mật hãy nhận thưởng kịp thời trước khi hoạt động kết thúc."
  },
  Mail_18021_Name = {
    Text = "Thông báo nhận thưởng lệnh huấn luyện"
  },
  Mail_18021_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_18029_Desc = {
    Text = "Xin chào, Người Giữ Gìn, đây là phần thưởng xếp hạng bạn nhận được trong Giấc mơ thám hiểm."
  },
  Mail_18029_Name = {
    Text = "Phần thưởng bảng xếp hạng Giấc mơ thám hiểm"
  },
  Mail_18029_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_18031_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n\nCon đường phía trước dài và đầy chông gai, trong những thời khắc khó khăn này, chúng ta càng cần phải đoàn kết và cùng nhau tiến lên. \nKèm theo thư này là liều lượng linh phìpeptide được phê duyệt đặc biệt hôm nay, xin vui lòng nhận. \nChúc cho chìa khóa bạc dẫn lối cho quý vị. \nNgoài ra: Lần phát hành đặc biệt này đã kết thúc, cảm ơn sự nỗ lực và cống hiến của quý vị. \n\nBan Hậu cần Hội đồng Trường Misaque"
  },
  Mail_18031_Name = {
    Text = "Cấp phát tiếp tế trong khoang chứa"
  },
  Mail_18031_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_18034_Desc = {
    Text = "Xin chào, Người Giữ Gìn, bạn vẫn chưa nhận phần thưởng từ việc tích lũy trong Giấc mơ thám hiểm sâu thẳm. Hiện tại, phần thưởng đã được gửi đến bạn qua phụ lục email."
  },
  Mail_18034_Name = {
    Text = "Phần thưởng tích lũy của \"Giấc mơ thám hiểm\" chưa nhận"
  },
  Mail_18034_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_18035_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n\nCon đường phía trước dài và đầy gai góc. Trong những thời khắc khó khăn này, chúng ta cần đồng lòng hợp tác để cùng tiến bước. \nKèm theo thư này là dưỡng chất linh phì đặc biệt được phê duyệt cho ngày hôm nay, xin vui lòng nhận. \nNguyện chìa khóa bạc soi sáng con đường phía trước. \nNgoài ra: Thời gian còn lại của phần bổ sung đặc biệt của bạn là {s1} ngày, xin hãy sắp xếp thời gian điều tra một cách hợp lý. \n\nBan Hậu cần Hội đồng Trường Misaque"
  },
  Mail_18035_Name = {
    Text = "Cấp phát tiếp tế trong khoang chứa"
  },
  Mail_18035_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_20231_Desc = {
    Text = "Thân gửi Người Giữ Gìn, mùa giải mới của đối đầu pha đã bắt đầu, hạng của bạn đã được đặt lại từ {s1} thành {s2}. Phần thưởng hạng mùa giải mới đã được đặt lại, nâng hạng để nhận thêm nhiều phần thưởng và danh vọng! {s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "Email mùa giải đối đầu pha"
  },
  Mail_20231_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_21453_Desc = {
    Text = "Kính thưa Người giữ gìn:\n\nTôi xin phép làm phiền, không biết dạo này bạn có khỏe không?\nXin lỗi vì đã làm phiền bạn trong lúc bận rộn, Jenkin và nhóm đã chuẩn bị một bữa tiệc sinh nhật nhỏ cho tôi, tôi đã suy nghĩ rất lâu, quyết định tự gửi lời mời này cho bạn.\nHầu hết những đứa trẻ mồ côi mà xưởng đón nhận không nhớ được ngày sinh của mình, cô Sarah đã chọn ngày chúng tôi vào trại trẻ mồ côi làm sinh nhật của mình. Chỉ riêng tôi là khác biệt, cô Sarah nói rằng tôi đã bị bỏ rơi tại cửa trại cứu tế vào một đêm đông cực kỳ lạnh giá, cô ấy muốn cuộc đời tôi không còn băng giá và tẻ nhạt nên đã chọn một ngày ấm áp làm sinh nhật của tôi. Vì vậy, đó là một ngày của tôi, ngày được quan tâm và yêu thương. Đây là một ngày quan trọng đối với tôi, tôi hy vọng Người giữ gìn cũng có thể đến chia sẻ với tôi, đây là Ước nguyện Nhỏ của tôi. Tất nhiên, nếu không thể được, cũng không sao cả vì Người giữ gìn có nhiều việc phải xử lý, Aigis biết điều đó.\nNếu lời mời này gây phiền phức nào cho bạn, hãy cho tôi biết và nhận lời xin lỗi chân thành của tôi. Nhưng nếu chẳng may bạn thực sự có thể dành thời gian đến, cũng rất rất chào mừng bạn đến tham gia cuộc vui của họ, có thể sẽ rất thú vị đấy, dù gì thì cũng là Jenkin đã chuẩn bị mà.\n\nAigis"
  },
  Mail_21453_Name = {
    Text = "Xin lỗi đã làm phiền trong lúc bận rộn…"
  },
  Mail_21453_Sender = {Text = "Aigis"},
  Mail_21454_Desc = {
    Text = "Êi: \nTôi vẫn luôn không hiểu, ngày sinh có gì đáng để ăn mừng đến vậy? Tại sao mọi người lại phải làm rùm beng như thế? \nNăm ngoái vào hôm nay, có một học sinh đến hỏi tôi về ngày sinh của mình. Buồn cười thật, khi tôi ra đời, hành tinh này còn chưa có khái niệm về thời gian, huống chi là sinh nhật. Nhưng cô ấy cứ quấn quít lấy tôi, nên tôi đành bảo rằng \"đó là lúc ngày và đêm giao nhau cân bằng\", không rõ cô ấy đã hiểu thế nào. \nViết thư này để nhắc bạn, sau 12 giờ đêm nay nhớ dọn những bông hoa trước cửa phòng tôi đi, ám chết được! \n\nLơ-tan"
  },
  Mail_21454_Name = {
    Text = "Những bông hoa…"
  },
  Mail_21454_Sender = {Text = "Lotan"},
  Mail_21455_Desc = {
    Text = "Erika hôm nay đã mang đến một túi cà phê lớn, nói rằng đó là món quà sinh nhật của tôi, và còn nói rằng bên trong là khẩu phần của bạn cho cả năm nay.<Del:Nhưng bạn có tự nguyện không? Nếu không>\n Nếu đây là trò đùa của Đóa hay ai đó khác, thì dù rất tiếc, tôi vẫn có thể trả lại nó... cho bạn. Dù sao đó cũng là cà phê! Tôi ít uống hai tách mà đã mệt muốn ngủ, không uống cả năm? Bạn sẽ ngủ như Tulô mất. Không phải là anh ấy không tốt, chỉ là, thứ màu đen thường xuất hiện vào ban đêm... Nói chung, nếu bạn cần, hãy lấy cà phê về bất cứ lúc nào, tất nhiên nếu bạn để cà phê ở đây, <Del:Tôi cũng vậy, thì> tôi nghĩ tôi sẽ rất vui mừng. Như vậy tôi cuối cùng có thể thực hiện thí nghiệm mà tôi muốn: chiết xuất và cô đặc caffein thành thuốc có thể hấp thụ qua da, dán lên người và luôn giữ tỉnh táo, mãi mãi...\n\n\nWenkel rất hy vọng được thực hiện thí nghiệm này"
  },
  Mail_21455_Name = {
    Text = "Cà phê……"
  },
  Mail_21455_Sender = {Text = "Winkle"},
  Mail_21456_Desc = {
    Text = "Sinh nhật? \n Nếu phải nói, sinh nhật của tôi không phải là một ngày tốt lành. Hàng trăm, hàng nghìn sức sống vô tội đã chết vào ngày đó, chỉ để cho tôi \"ra đời\", sau đó đi giết thêm nhiều người hơn. \n Vì vậy, ngày này cũng không có gì đáng để ăn mừng. Nhưng tôi hiểu các bạn loài người đều là những sinh vật rất coi trọng \"cảm giác nghi lễ\", và tôi vừa có một số tiền trong tay — yên tâm, đó là tiền tôi kiếm được bằng mồ hôi tại câu lạc bộ cá Hồi, không phải thu nhập bất hợp pháp. \n Hãy nhận lấy số tiền này, mua cho bản thân một quà tặng đi, coi như là để chúc mừng sinh nhật của tôi. \n\n Yu U Hahi"
  },
  Mail_21456_Name = {
    Text = "Sinh nhật……"
  },
  Mail_21456_Sender = {Text = "Uvhash"},
  Mail_21457_Desc = {
    Text = "Người giữ bí mật: \n\nTrong địa giới của Misaque, có tồn tại phong tục chúc mừng sinh nhật không? \nĐất nước trong ký ức của tôi... mỗi năm đều tổ chức nghi lễ long trọng để mừng ngày sinh của đức vua. \nDần dần, ý nghĩa đặc biệt của \"sinh nhật\"đã được dành cho tất cả mọi người. \nTừ thời xa xưa, mỗi dịp sinh nhật, đồng nghiệp và bạn bè đều từ phương xa đến bên tôi. \nCảm giác được những người thân yêu vây quanh... cảm giác ấm áp như được mặt trời ôm ấp... có lẽ chính là lý do khiến tôi không thể buông bỏ quá khứ. \nÀ... tôi đã đi quá xa rồi, tôi có làm phiền công việc của ngài không? \nTôi đã chuẩn bị một số món trà bánh thường dùng trong quá khứ, muốn chia sẻ cùng ngài. \nNếu ngài vui lòng ghé qua, hãy tìm tôi sau bữa tối nhé. \n\nPháp Luân Tư"
  },
  Mail_21457_Name = {
    Text = "Ánh sáng bất diệt.."
  },
  Mail_21457_Sender = {Text = "Faros"},
  Mail_21458_Desc = {
    Text = "Hôm nay thực sự là một ngày đáng kỷ niệm: vào ngày này, vị Chúa tể vĩ đại của Goliath, Vua của những người khổng lồ, đã giáng thế; vào ngày này, biển cả rung chuyển, sao trời mờ nhạt. \n Nghe nói trong khuôn viên trường không cho phép lãng phí, vậy hãy tổ chức tiệc sinh nhật của tôi với quy mô bằng một phần mười so với trước đây — mười con heo sữa quay, một trăm xiên bạch tuộc nướng và một ban nhạc có thể biểu diễn dân ca Goliath. À, tốt nhất cũng nên có một tá vũ nữ… \n Gì cơ, tất cả những thứ đó đều không được phép sao? \n Vậy thì chỉ cần vũ nữ thôi… không cần một tá, bốn hoặc năm người là đủ. \n Gì cơ, ngay cả điều đó cũng không được phép?! \n Quy mô như vậy thật không xứng đáng với thân phận của ta. Giờ ta tuyên bố, kế hoạch tiệc tối bị hủy bỏ! \n\n Goliath"
  },
  Mail_21458_Name = {
    Text = "Kế hoạch bữa tối.."
  },
  Mail_21458_Sender = {Text = "Goliath"},
  Mail_21459_Desc = {
    Text = "Người giữ bí mật——\n\n Hôm nay khi làm bài tập ghi nhớ bên phía bà Sylvia, bà ấy đã hỏi về sinh nhật của tôi. Bạn cũng biết đấy, vừa mới đặt cái cờ lê xuống là tôi đã quên ngay, làm sao mà nhớ được sinh nhật! Càng nghiêm trọng hơn, đây còn là một điều chỉ mình tôi biết, tôi! Sinh nhật này coi như không có. \n\n Nhưng cha Salvador nói rằng ngày cụ thể không quan trọng, điều quan trọng là tôi kỷ niệm điều gì mỗi ngày, vì vậy tôi đã quyết định, hôm nay chính là sinh nhật của tôi! Tôi đã hẹn với một người (tôi quên mất người đó là ai, chắc chắn không phải bạn chứ, Người Giữ Gìn?) tổ chức tiệc tại cửa nhà ăn, bạn nhất định phải đến đấy nhé! \n\n\n\n Nhất định sẽ nhớ ngày sinh nhật này, Notira \n\n\n\n Một tờ giấy được gửi cùng với bức thư: \n\n Đứa trẻ đó viết xong thư liền vội vàng đi, để quên cả bức thư và một số món quà nói là dành cho bạn trên bàn. \n Tôi đã đính kèm tất cả vào phong bì, mong được gặp bạn tại bữa tiệc tối nay. Yên tâm đi, tôi sẽ nhắc nhở cô ấy đến dự tối nay. \n\n —Sylvia"
  },
  Mail_21459_Name = {
    Text = "Tôi quyết định sinh nhật của mình!"
  },
  Mail_21459_Sender = {Text = "Nautila"},
  Mail_21460_Desc = {
    Text = "Nhóc con:\n\nTrong Biển Nguyên Chất không có tinh tú nhật nguyệt, cũng không có bốn mùa luân chuyển, vì vậy, sinh nhật của ta nên được ghi là【Không rõ】.\nNhưng hôm nay quả thực là một ngày quan trọng, dù sao thì hình dáng này cũng được thừa hưởng từ một con người mang「Tâm Nguyện」. Cô ấy thích sự náo nhiệt, nên đã mở cửa tiệm nhỏ này, nhưng vì đi điều tra khắp nơi, sinh nhật cô ấy thường chỉ có mình ta bầu bạn. Để hoàn thành tâm nguyện lúc sinh thời của cô ấy, Tiệm Giải Ưu hôm nay sẽ tổ chức tiệc nến, trân trọng mời các khách hàng trung thành đến tham dự.\nTất nhiên, Tiệm Giải Ưu cũng sẽ dành cho tất cả khách đến một khoản giảm giá nhỏ, xin nhóc con đừng bỏ lỡ nhé.\n\nDaphodel"
  },
  Mail_21460_Name = {
    Text = "Ước nguyện nhân gian…"
  },
  Mail_21460_Sender = {
    Text = "Hoa thuỷ tiên"
  },
  Mail_21461_Desc = {
    Text = "Khi bị đưa đi khỏi gia đình, mẹ nuôi... phu nhân thống chế đã đập nát những mảnh gốm ghi lại ngày sinh của tôi, đập nát quá khứ khi tôi từng là người Delos. Ngày sinh thực sự, đương nhiên đã không còn cách nào để nói đến. \n Sau khi chia tay Laï, tôi cũng suy nghĩ một phen... Nếu coi đêm tôi trốn thoát khỏi nhà tù, bắt đầu trả thù làm \"ngày sinh\" của tôi, anh thấy sao? \n Mặc dù bây giờ đã không cần thiết phải kỷ niệm việc thêm một tuổi, nhưng như một dấu hiệu của sự thay đổi thời gian, dường như cũng không tồi."
  },
  Mail_21461_Name = {
    Text = "Ngày sinh ra"
  },
  Mail_21461_Sender = {Text = "Helot"},
  Mail_21462_Desc = {
    Text = "Kiểm tra, kiểm tra. \nKính gửi Người Giữ Gìn, chào bạn. Nếu bạn nhận được bức thư này, điều đó có nghĩa là ý kiến của bạn đối với Erika cực kỳ quan trọng và đã được chọn tham gia vào kế hoạch kiểm tra và bảo dưỡng mô-đun ngôn ngữ hàng năm của con rối tự động Erika. Lần đánh giá này sẽ được thực hiện dưới dạng câu hỏi ngắn, yêu cầu bạn đánh giá chức năng của mô-đun ngôn ngữ EA-L-1033 mới được cài đặt cho con rối tự động Erika. Điều này sẽ không mất nhiều thời gian, xin đừng lo lắng. \nCâu hỏi ngắn: \nBạn có hiểu nội dung chính của bức thư này không? \n\nHãy viết câu trả lời của bạn trực tiếp vào phần trống bên dưới câu hỏi ngắn và đóng lại lá thư vào phong bì. \nCảm ơn sự tham gia của bạn. \n\nErika"
  },
  Mail_21462_Name = {
    Text = "Thử nghiệm, thử nghiệm……"
  },
  Mail_21462_Sender = {Text = "Erica"},
  Mail_21463_Desc = {
    Text = "Người giữ bí mật: \n\nBạn là người hiếm hoi còn tỉnh táo trong ngôi trường này, ánh mắt của bạn có thể xuyên thấu thân hình bất toàn này, nhìn thấy con người thật của tôi. \nVới khả năng của bạn, chắc chắn có thể giải thích rõ ràng cho những đứa trẻ kia: Tôi không phải tiên cá, thân xác này rồi sẽ vượt biển leo núi để hoàn thiện bản thân. \n… Thôi, cũng không làm khó bạn. Nhưng ít nhất hôm nay, đừng để chúng nghịch đuôi của tôi nữa. \nHôm nay là một ngày đặc biệt. Nếu bạn có thời gian, tôi có vài điều muốn nói trực tiếp với bạn. \n\nKẻ khắc sét"
  },
  Mail_21463_Name = {
    Text = "Thân thể hoàn hảo……"
  },
  Mail_21463_Sender = {Text = "Caecus"},
  Mail_21464_Desc = {
    Text = "Người giữ bí mật: \n\nNgày sinh của tôi theo nghĩa thông thường, là ngày cha nhận nuôi tôi. \nTrước đây, ông luôn coi trọng ngày này, mỗi năm đều tổ chức vũ hội lớn —— mặc váy nhảy múa còn mệt hơn cả luyện kiếm ba nghìn lần. \nNhưng đó là lòng yêu thương của cha, tôi không muốn phụ lòng tình cảm quý giá này. \nTuy nhiên năm nay, ông cuối cùng cũng đồng ý để tôi tự sắp xếp lịch trình sinh nhật. Có lẽ trong mắt cha, tôi đã không còn là đứa trẻ cần phải giám sát mọi lúc nữa. \nÀ, bạn có thể đi cùng tôi lên đỉnh tháp đồng hồ không? Chúng ta có thể nói chuyện và hóng gió. \nNghe nói, đêm nay sẽ là một đêm trăng tròn tuyệt đẹp. \n\nRamona"
  },
  Mail_21464_Name = {
    Text = "Mặt trăng tròn…"
  },
  Mail_21464_Sender = {Text = "Ramona"},
  Mail_21465_Desc = {
    Text = "Kính thưa, người chủ thân yêu nhất của tôi: \n Đúng vậy, hôm nay chính là sinh nhật lần thứ @1 của Gia Lân (tuổi của phụ nữ cần được giữ kín)! \n Để chuẩn bị cho ngày này, Gia Lân đã tổ chức một bữa tiệc vô cùng đặc biệt và mời tất cả những người bạn có thể mời~! Mặc dù cuối cùng chỉ có Ô Ryta, Orci và Lily đồng ý đến… \n Nhưng không sao cả, nơi nào có người thì nơi đó có tiệc tùng, nơi nào có tiệc tùng thì nơi đó có Gia Lân! Gia Lân còn chuẩn bị cẩn thận món \"phiên bản cải tiến\" của món ếch hầm, ốc sên bùn tỏi và canh dơi cà ri, chủ nhân nhất định phải đến thử nhé~ \n \n Xin hỏi nhỏ, chủ nhân chắc chắn đã chuẩn bị quà tặng cho Gia Lân rồi chứ? Nhớ là phải lấp lánh đấy nhé! \n \n Người hầu gái luôn khiêm tốn của ngài \n Gia Lân"
  },
  Mail_21465_Name = {
    Text = "Quà tặng……"
  },
  Mail_21465_Sender = {Text = "Karen"},
  Mail_21466_Desc = {
    Text = "<Del:Người Giữ Bí Mật> lão làng Khu Tây thân mến:\nĐây là một bức thư <Del:mời mọi gọi mời mọi mời gọi mời mọi> nói tóm lại là mời cậu đến ăn bánh kem miễn phí, tiện thể chúc mừng sinh nhật tớ! Thực ra cũng là để cảm ơn cậu đã giúp tớ tìm được chị gái trước đó, còn đưa tớ đến đây, cho tớ và Brown một nơi có thể yên tâm ở lại.\n(Những dòng trên là Aegis bảo tớ viết đấy, sến lắm. Tình bạn giữa chúng ta đâu cần những thứ này, đúng không, Người Giữ Bí Mật?)\nTóm lại, tối nay ở sân sau phòng ký túc của cậu, tớ, Brown và Aegis đã tự tay chuẩn bị một số thứ ngon lành, đợi cậu đến cùng thưởng thức! Tất nhiên chủ yếu là Aegis làm, đồ cô ấy làm ngon lắm, các bà các cô trong bếp đều khen cô ấy có năng khiếu đấy, cậu mà không đến thì đảm bảo hối hận.\n\nBạn cũ của cậu, Jenkin và Brown"
  },
  Mail_21466_Name = {
    Text = "Thân yêu người Tây thân mến…"
  },
  Mail_21466_Sender = {Text = "Jenkin"},
  Mail_21467_Desc = {
    Text = "Người giữ gìn:\n\nKhi mọi người vẫn sống trong vương quốc của thần, chúng tôi đã bắt đầu dùng nhảy múa để thể hiện cảm xúc của mình - vòng xoay cuồng nhiệt, những bước đi đầy bi ai... Có người nói rằng lịch sử nhảy múa dài như lịch sử loài người, nó đã chứng kiến cả sự huy hoàng và suy sụp của chúng ta.\n\nTôi từng nói rằng sẽ không nhảy nữa, nhưng... dẫu sao tôi cũng được sinh ra để nhảy. Vì vậy, chỉ hôm nay, bạn có sẵn lòng nhảy cùng tôi không? Hòa mình vào, cảm nhận những chuyển động sâu thẳm trong cơ thể.\n\nTôi sẽ đợi bạn trong phòng tập nhảy.\n\n\n\nLiz"
  },
  Mail_21467_Name = {
    Text = "Lời mời nhảy cùng"
  },
  Mail_21467_Sender = {Text = "Liz"},
  Mail_21468_Desc = {
    Text = "Kính gửi Người giữ gìn:\n\nTrước khi tôi trở thành Người đánh thức, các dịp sinh nhật của tôi đều là với đồng đội đem rượu từ ngoài trại lính về, lén lút tổ chức trong lều chứa vật liệu và bánh mì đen phân phát, sau đó trước khi sĩ quan phát hiện, ném chai rượu ra ngoài bãi cỏ.\n\nNhưng Mythag không phải là quân đội, ở đây, chúng ta có thể hoàn toàn phóng túng. Không biết bạn có muốn cùng tôi chia sẻ một chai rượu ngon, cùng tổ chức lễ sinh nhật của tôi không?\nNếu bạn sẵn lòng, vào tối nay khi mặt trăng vượt qua tháp chuông, hãy đến sân thượng của ký túc xá. Không biết bạn có chú ý không, ở đó có cảnh vật đẹp nhất của toàn Mythag.\n\n\n\nAlva"
  },
  Mail_21468_Name = {
    Text = "Chia sẻ rượu ngon…"
  },
  Mail_21468_Sender = {Text = "Alva"},
  Mail_21469_Desc = {
    Text = "Bãi biển bãi biển bãi biển bãi biển!\nÊ? Đầu thư phải viết tên người nhận——thật phiền phức! Rõ ràng Người Giữ Gìn dán giấy ghi chú trên tủ lạnh cũng không viết tên người nhận mà!\nHôm nay là sinh nhật của Ô Ryta… ờ… bao nhiêu tuổi nhỉ? Dù sao thì cũng là sinh nhật của Ô Ryta!\nĐây là kho báu của Ô Ryta! Tất cả đều tặng bạn! Hãy đưa Ô Ryta đi chơi ở bãi biển nhé, làm ơn, làm ơn, làm ơn!\nCoi như, coi như là món quà tặng sinh nhật cho Ô Ryta đi, được không nào~\n\nÔ Ryta"
  },
  Mail_21469_Name = {
    Text = "Bãi biển!"
  },
  Mail_21469_Sender = {Text = "Aurita"},
  Mail_21470_Desc = {
    Text = "Quý nhân:\n\nQuá khứ khi ở trên hành tinh hoang vu cùng chị gái, chúng tôi luôn ôm nhau, hút năng lượng từ cùng một cây thực vật, để kỷ niệm sự ra đời của chúng tôi. \nNhững ngày đó tuy đắng cay, nhưng giờ nghĩ lại, cũng không khỏi cảm thấy vui vẻ và ấm áp. \nHôm nay lại là ngày kỷ niệm sự ra đời của chúng tôi, nếu được, tôi có thể dùng một bài hát để đổi lấy một đoạn cành không? \nMột đoạn cành ngọt ngào, có thể đại diện cho quá khứ của tôi và chị gái, có thể đại diện cho tương lai của tôi và ngài…\n\ntinkerer"
  },
  Mail_21470_Name = {
    Text = "Bài hát sinh nhật"
  },
  Mail_21470_Sender = {Text = "Tinct"},
  Mail_21471_Desc = {
    Text = "Nhận ân huệ lớn, Người Giữ Gìn của Đại học Misag, chúa tể hiền minh và nhân đức: \nVạn an! \nMấy ngày trước, tôi thấy có xe tải ra vào chuồng ngựa của trường, hóa ra là đưa đến một con ngựa ôn huyết. Nhớ lại lần điều tra cùng chúa tể, ngài từng nói chưa từng có trải nghiệm cưỡi ngựa. Ngựa ôn huyết con non rất hiền lành, phù hợp nhất để người mới làm quen với lưng ngựa. \nCưỡi ngựa, đuổi theo bình minh và hoàng hôn, đó là khoảnh khắc thoải mái nhất trong ký ức của tôi. Nếu chúa tể tin tưởng, nguyện cùng tôi cưỡi ngựa, tôi muốn chia sẻ cảm giác thoải mái này với ngài. \n\nOrci"
  },
  Mail_21471_Name = {
    Text = "Ngựa máu ấm…"
  },
  Mail_21471_Sender = {Text = "Ogier"},
  Mail_21472_Desc = {
    Text = "Lịch pháp cố quốc, khác xa so với lịch đang dùng ở Londinium ngày nay.\nTa sinh vào ngày Mãn Tinh thứ năm của tháng Hạ thứ hai, chọn ngày hôm nay để chúc mừng là kết quả tính toán của người phụ trách phòng thí nghiệm.\nKhi cố quốc còn tồn tại, Chủ Tế sẽ lo liệu mọi thứ. Sau đại lễ tế tự, cả nước hoan hỉ, bước vào kỳ nghỉ kéo dài bảy ngày.\nDù không phải điều ta mong cầu, nhưng ta cũng không có lý do ngăn cản niềm vui lan tỏa.\nHôm nay không phải ngày nghỉ công của Misager, và trách nhiệm của Người Giữ Bí Mật cũng định sẵn rằng ngươi sẽ không có ngày nghỉ đều đặn.\nNhưng, nếu lấy lý do chúc thọ ta để xin nghỉ phép, nghĩ rằng Ban Quản Lý cũng không dám có ý kiến gì.\nHãy tận hưởng một buổi chiều thư thái.\n\nTuru"
  },
  Mail_21472_Name = {
    Text = "Ngày sinh…"
  },
  Mail_21472_Sender = {Text = "Tulu"},
  Mail_21473_Desc = {
    Text = "Người giữ bí mật: \n\nÔ Ryta nói, những người sinh nhật đều phải ước nguyện. \nCòn tôi lại là người không bao giờ ước nguyện. \nBởi vì suy nghĩ của tôi luôn trở thành hiện thực. Điều này không phải do may mắn, mà giống như một loại... hướng dẫn định mệnh? \nGiống như khi tôi đi biển cùng Hilaster tháng trước, tôi lại \"vô tình\" nhặt được một viên hóa thạch đẹp. \nNgười dân địa phương gọi nó là \"Hải Bách Hợp\". Cánh tay của nó giống như cối xay gió đón dòng nước, đang lười biếng tận hưởng ánh mặt trời buổi chiều mùa hè. \nYếu đuối, đẹp đẽ. Khi nhìn thấy nó, hình ảnh của bạn tự nhiên xuất hiện trong đầu tôi. \nLần này tôi vẫn không ước nguyện — \nBạn chắc chắn sẽ thích, phải không? \n\nsơn"
  },
  Mail_21473_Name = {
    Text = "Hải bách hợp.."
  },
  Mail_21473_Sender = {Text = "Sanga"},
  Mail_21475_Desc = {
    Text = "Người giữ bí mật: \n\nTrong quá khứ, khi đi tàu với Elton, anh ấy sẽ nấu một bữa ăn vào ngày này hàng năm và muốn tôi 「ước」. \nTrước khi đến đây, tôi không hiểu 「ước」 là gì. Bây giờ, tôi không biết mình có thể ước gì… \nCó lẽ, tìm thấy 「ước」 cũng có thể là một 「ước」? \n\nHilaster"
  },
  Mail_21475_Name = {
    Text = "Mong muốn…"
  },
  Mail_21475_Sender = {Text = "Celeste"},
  Mail_21476_Desc = {
    Text = "Người giữ bí mật: \n\nÔ Ryta nói với tôi, bạn sẽ thực hiện tất cả những điều ước vào sinh nhật, đúng không? \nChắc không phải thật đâu nhỉ? Để thực hiện tất cả điều ước của mọi người thì cũng phiền bạn quá. \nNhưng nếu có thể ước... tôi muốn tinkerer có một sân khấu rộng lớn hơn. \nCó khó thực hiện quá không? Hừm... vậy, vậy đổi thành \"trong năm tới, trên bàn ăn của tôi sẽ không còn xuất hiện cần tây\", được không? \n\nPhiệt"
  },
  Mail_21476_Name = {
    Text = "Mong muốn…"
  },
  Mail_21476_Sender = {Text = "Faint"},
  Mail_21477_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n\n Hãy để tôi tiết lộ một bí mật: sinh nhật này thực ra là giả. Về ngày tháng sinh thật sự của tôi… hãy để nó tan biến theo gió. \n Sau khi bị bệnh, anh trai luôn nhờ người quản gia chuẩn bị một chiếc bánh nhỏ cho tôi vào ngày sinh nhật. \n Không có bài hát sinh nhật, cũng không có lời chúc phúc, giống như việc tổ chức sinh nhật là một điều đáng xấu hổ. \n Bây giờ, mọi thứ đã khác. Tôi có thể đi dưới ánh mặt trời, hát to và tổ chức sinh nhật. \n Đó chỉ là những niềm vui nhỏ bé, nhưng lại khiến tôi cảm thấy hoài niệm. \n Cảm ơn bạn, Người Giữ Gìn. \n\n (Tất nhiên, nếu bạn và mọi người đối xử thô lỗ với tôi hơn nữa… thì sẽ hoàn hảo hơn.) \n\n Reia"
  },
  Mail_21477_Name = {
    Text = "Một bí mật.."
  },
  Mail_21477_Sender = {Text = "Leigh"},
  Mail_21478_Desc = {
    Text = "Ngục·tù·nhỏ của tôi: \n\nTôi đã lâu·lâu·lâu không vung roi nữa rồi—— \nBị mắc kẹt trong ngôi trường vô vị này, bị giam hãm trong bộ đồng phục, lòng Pandia ngứa ngáy như thể có một chú mèo tinh nghịch đang cào vào vậy. Không những chẳng ai hiểu tôi, mà những nhân viên còn tìm mọi cách ngăn cản tôi \"tìm niềm vui\"—— thật quá đáng! \nÔi, hôm nay là một ngày đặc biệt, rất thích hợp để roi của tôi chạm lại vào làn da mềm mại, để tôi nghe thấy tiếng hát lên vì đau đớn... Nếu hôm nay bạn có thời gian, hay là, đến tìm tôi trò chuyện nhé~? \n\nPandia"
  },
  Mail_21478_Name = {
    Text = "Tiếng roi…"
  },
  Mail_21478_Sender = {Text = "Pandia"},
  Mail_21479_Desc = {
    Text = "<Big:Buổi biểu diễn kỷ niệm của Đại sư Phép thuật Kassia, chỉ hôm nay!>\n\nĐể cảm ơn sự ủng hộ và khích lệ của quý khán giả qua nhiều năm, để đáp lại niềm vui mà quý khán giả đã mang lại trong quá khứ, Đại sư Phép thuật Kassia quyết định vào lúc 8 giờ tối nay, tại sân trung tâm Đại học Misag (bên cạnh tượng Phillips), tổ chức buổi biểu diễn kỷ niệm đặc biệt! Tối nay, bạn sẽ được chứng kiến một sân khấu rực rỡ hơn bao giờ hết, một buổi biểu diễn hấp dẫn hơn, và — quan trọng nhất — những phép thuật hoành tráng đến mức bạn sẽ không thể tin vào mắt mình! Ngay cả Não bộ của Misaque có mặt tại hiện trường cũng sẽ bị chinh phục bởi phép thuật vượt xa trí tưởng tượng, đây là lời cam kết của Đại sư Kassia!\n\nCơ hội hiếm có, chỉ duy nhất tối nay, hoàn toàn miễn phí! Đại sư Kassia hẹn gặp bạn!\n\n<Small:Lưu ý: Nếu xuất hiện các triệu chứng như mệt mỏi tinh thần, buồn bã sau hoặc trong quá trình biểu diễn, Đại sư Kassia không chịu trách nhiệm.>\n<Small:PPS: Mọi tuyên truyền liên quan đến Não bộ của Misaque đều dựa trên thực tế tại thời điểm diễn ra, Đại sư Kassia giữ quyền giải thích tất cả về chương trình và hiệu ứng của chương trình.>"
  },
  Mail_21479_Name = {
    Text = "Sự kiện kỷ niệm sinh nhật của Đại sư Pháp thuật Kassia!"
  },
  Mail_21479_Sender = {Text = "Casiah"},
  Mail_21480_Desc = {
    Text = "Này, hôm nay là sinh nhật của tôi, quà đâu rồi?\nCái gì, bạn quên chuẩn bị rồi...? Hừ, tôi đã đoán sẽ như vậy.\nNày, bạn cầm cuốn lịch này, bên trên ghi rõ ngày sinh của tôi, ngày giỗ của tôi, ngày kỷ niệm lần đầu đến Mythag, cùng với ngày lễ vui chơi, lễ thần nông... những ngày lễ này chúng ta đều phải cùng đón, tóm lại lần sau đừng quên nhé!\n\nNếu bạn lại quên...\nHình như tôi cũng không thể làm gì bạn, hừ.\nTóm lại vẫn không được quên.\n\nAgrippa"
  },
  Mail_21480_Name = {Text = "Ê.."},
  Mail_21480_Sender = {Text = "Agrippa"},
  Mail_21481_Desc = {
    Text = "Người giữ bí mật: \n\nTôi vốn không muốn viết bức thư này, nhưng dường như việc vận hành của Erika đã gặp vấn đề, chuông báo động của cô ấy reo liên tục cho đến khi tôi viết xong bức thư này. \nNgày sinh nhật đối với tôi chỉ là một ngày không có ý nghĩa, tỷ lệ thành công của thí nghiệm sẽ không cao hơn những ngày khác, và chỉ số Nos của tôi cũng sẽ không thay đổi vì ngày này. Nhưng Ramona kiên quyết biến ngày này thành \"ngày nghỉ\" của tôi, đồng thời hạn chế quyền truy cập vào phòng thí nghiệm của tôi trong hôm nay. \nTôi không có nơi nào để đi, vì vậy hôm nay tôi sẽ tiến hành kiểm tra toàn diện các báo cáo trước đây của bạn. \nHãy đến phòng lưu trữ sau bữa tối. Lưu ý, đừng mang bánh vào phòng lưu trữ, tài liệu giấy rất mong manh. \n\nđóa"
  },
  Mail_21481_Name = {
    Text = "Sau bữa tối…"
  },
  Mail_21481_Sender = {Text = "Doll"},
  Mail_22435_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \nBan đầu tôi chọn đọc thơ trong khuôn viên trường vào lúc bình minh vì nghĩ rằng thời gian này ít người qua lại hơn, dễ dàng đắm chìm vào thế giới thơ hơn. Sau đó, tôi cũng dần yêu thích bầu trời sáng dần của buổi sáng sớm, những giọt sương long lanh và tiếng chim hót thanh thúy, uyển chuyển. \nĐiều tôi không ngờ là có rất nhiều thầy cô và học sinh âm thầm theo dõi tôi và đã thành lập một câu lạc bộ thơ. Hôm nay là sinh nhật của tôi, đúng vào thời điểm hoa thủy tiên đang chuẩn bị nở, họ dự định tổ chức một buổi thưởng thức thơ, cùng nhau ngắm cảnh và đọc thơ trong khuôn viên trường. \nTrong khung cảnh này, tôi mong bạn có thể đến cùng thưởng thức. \n\nNinh Phi Nga"
  },
  Mail_22435_Name = {
    Text = "Thư mời tham gia buổi đọc thơ"
  },
  Mail_22435_Sender = {Text = "Nymphaea"},
  Mail_23897_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Trong bản cập nhật V1.0.21, chúng tôi đã điều chỉnh phần thưởng lần đầu vượt qua các mức độ khó khăn của \"điều tra hành động\", các màn chơi chiến đấu \"duy thức tiềm hành\"ở mức độ thường và khó khăn, cũng như các khe hở luân chuyển I-IV của các giới vực trong \"Vùng đất vô ánh sáng\". Nội dung điều chỉnh chi tiết có thể xem trong \"V1.0.21 thông báo bảo trì trực tuyến\". \n        Dựa trên bản ghi điều tra và hoàn thành trước đó của bạn, chúng tôi sẽ phát hành một lần duy nhất phần thưởng chưa nhận theo phần thưởng đã điều chỉnh. Chi tiết vui lòng xem trong phụ lục."
  },
  Mail_23897_Name = {
    Text = "Điều chỉnh bù đắp phiên bản V1.0.21"
  },
  Mail_23897_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_24199_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Trong bản cập nhật V1.0.24, chúng tôi đã kích hoạt lại Chương 5 của ‘Điều tra hành động’, phần đã tạm thời đóng cửa ở phiên bản V1.0.16. Theo nguyên tắc công bằng, chúng tôi sẽ cung cấp bồi thường tương ứng dựa trên sự thay đổi về phần thưởng trước và sau khi điều chỉnh, cũng như tình hình điều tra của từng Người Giữ Gìn. Bồi thường dựa trên hồ sơ điều tra của bạn đã được gửi vào phần phụ lục."
  },
  Mail_24199_Name = {
    Text = "Bồi thường cho việc mở lại chương 5 trong V1.0.24"
  },
  Mail_24199_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_24200_Desc = {
    Text = "Kính gửi Người Giữ Bí Mật: \n        \nTrong bản cập nhật V1.0.24, chúng tôi đã mở lại Chương Năm của \"Điều Tra Hành Động\", từng được tạm ngừng ở phiên bản V1.0.16. Để đảm bảo công bằng, chúng tôi sẽ cung cấp bù đắp phù hợp dựa trên sự thay đổi phần thưởng trước và sau điều chỉnh, cũng như tiến độ điều tra của từng Người Giữ Bí Mật. Dựa trên hồ sơ điều tra của bạn, lần này bạn không cần nhận bù đắp."
  },
  Mail_24200_Name = {
    Text = "Bồi thường cho việc mở lại chương 5 trong V1.0.24"
  },
  Mail_24200_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_24202_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Cảm ơn bạn đã ủng hộ và công nhận trò chơi \"Đêm trước khi quên\". Để Người Giữ Gìn có trải nghiệm tốt hơn tại Đại học Misag, chúng tôi chân thành mời bạn điền vào bảng khảo sát trải nghiệm dưới đây. Để cảm ơn sự hợp tác của bạn, chúng tôi đã chuẩn bị phần thưởng là \"bạc tâm\" × 200, hoàn thành bảng khảo sát bạn sẽ nhận được. \n        <SurveyLink:【Nhấp vào đây để điền】>\n        Chúng tôi sẽ lắng nghe nghiêm túc mọi ý kiến của từng Người Giữ Gìn, phản hồi của bạn chắc chắn sẽ giúp Đại học Misag ngày càng tốt hơn! \n        ——Nguyện chìa khóa bạc soi sáng con đường của bạn."
  },
  Mail_24202_Name = {
    Text = "Phiếu khảo sát trải nghiệm phiên bản V1.0 phần dưới"
  },
  Mail_24202_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_24280_Desc = {
    Text = "Xin chào, Người Giữ Gìn: \nTrong bảng xếp hạng cuộc điều tra Giấc mơ thám hiểm hôm qua, bạn đã đạt vị trí thứ {s2} trong \"{s1}\", với danh hiệu điều tra là \"{s3}\". Dưới đây là phần thưởng xếp hạng. Người giữ bí mật vui lòng kiểm tra."
  },
  Mail_24280_Name = {
    Text = "Phần thưởng hàng ngày của bảng xếp hạng Giấc mơ thám hiểm"
  },
  Mail_24280_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_24877_Desc = {
    Text = "Người giữ bí mật: \n\nMỗi sinh nhật của tôi đều là một bữa tiệc salon hoành tráng, khách mời đông đảo, vui vẻ. \nNhưng lần này, tôi có một ý tưởng khác —— \nNgồi ở vị trí chủ nhân quá lâu, thỉnh thoảng cũng muốn thử cảm giác làm khách. \nCó thể là một bữa tiệc salon tinh tế, hoặc một bữa cơm gia đình bình thường, mọi thứ do bạn quyết định, được chứ? \nTuy nhiên, nếu chọn mở thêm một bữa tiệc salon, đừng mời những người nổi tiếng và quý tộc nữa. \nNgày tốt lành hiếm có, tôi không muốn phải mỉm cười giả tạo. \n\n<Del:Quý bà đỏ>Sorrel"
  },
  Mail_24877_Name = {
    Text = "Tùy bạn quyết định…"
  },
  Mail_24877_Sender = {Text = "Sorel"},
  Mail_24878_Desc = {
    Text = "Chủ nhân: \n\nHôm nay là sinh nhật của Lily, Agrippa nói phải \"quậy tung lên một trận\".\nTrước đây mẹ và Lily tổ chức sinh nhật không phải như vậy, mẹ sẽ đội cho con chiếc mũ chóp nhọn, cùng nhau vỗ tay thổi nến.\nLily không biết, phải làm thế nào mới đúng, xin chủ nhân hãy ra lệnh. \n\nLily"
  },
  Mail_24878_Name = {
    Text = "Phiền não…"
  },
  Mail_24878_Sender = {Text = "Lily"},
  Mail_25147_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Trong bản cập nhật V1.1.0, phần thưởng điểm tích lũy hàng tuần của 「Giấc mơ thám hiểm」 đã bị gỡ xuống và thay thế bằng thử thách mới 「Mỗi tuần thử thách」. Dựa trên nguyên tắc công bằng, chúng tôi sẽ bồi thường phần thưởng điểm tích lũy hàng tuần chưa nhận cho những Người Giữ Gìn đã mở khóa 「Giấc mơ thám hiểm」 nhưng chưa nhận hết phần thưởng và đã đăng nhập vào trò chơi trước 5:00 ngày 15 tháng 1. Vui lòng kiểm tra."
  },
  Mail_25147_Name = {
    Text = "Bồi thường điểm thưởng Tuần này - V1.1.0 Giấc mơ thám hiểm"
  },
  Mail_25147_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_25148_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Trong bản cập nhật V1.1.0, phần thưởng hàng tuần của đối đầu pha (beta) đã bị gỡ bỏ, thay thế bằng thử thách hàng tuần, có cùng tiến độ và phần thưởng với thử thách hàng tuần trong Giấc mơ thám hiểm. Dựa trên nguyên tắc công bằng, chúng tôi sẽ bồi thường hạt ngọc tan rã ×1000 cho những Người Giữ Gìn đã mở khóa 「đối đầu pha (beta)」 trước đó, nhưng chưa hoàn thành hoặc nhận phần thưởng hàng tuần trong tuần này, và đã đăng nhập vào trò chơi trước 5:00 ngày 15 tháng 1 (UTC+8). Vui lòng kiểm tra."
  },
  Mail_25148_Name = {
    Text = "Phần thưởng bù hàng tuần của V1.1.0 đối đầu pha"
  },
  Mail_25148_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_25414_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n\nTrọng lượng của ngày sinh, đối với mỗi người đều không giống nhau. Nhưng sinh nhật của Người Giữ Gìn, đối với toàn bộ Misaque đều rất quan trọng. \nBà Sylva đã chuẩn bị bữa tiệc sinh nhật cho bạn ở khu ký túc xá, Giám đốc Học viện Kherat và Lord Dexter đều sẽ tham dự. Biết rằng mệt mỏi tinh thần của bạn vẫn chưa tan hết, tôi đã giúp bạn sắp xếp sẵn trang phục chính thức, treo ở tủ quần áo cạnh cửa, trước khi tham dự có thể trực tiếp thay vào. \nNăm nay rất vinh dự được đồng hành cùng bạn với tư cách là người bạn đồng hành, hy vọng năm sau cũng vậy. \nMong rằng chìa khóa bạc sẽ soi sáng con đường phía trước. \n\nP.S. Bánh ngọt nhỏ đặt riêng đã được Erika giao đến ký túc xá của bạn. \n\nNguyện làm người bạn đồng hành mãi mãi của bạn, Ramona"
  },
  Mail_25414_Name = {
    Text = "Ngày sinh…"
  },
  Mail_25414_Sender = {Text = "Ramona"},
  Mail_34667_Desc = {
    Text = "Kính gửi @1@2:\n\nThế giới đã quên mất tên của bạn.\nVì vậy tôi Hoán tỉnh bạn, như bạn đã Hoán tỉnh tôi. Trước khi tận thế đến, bạn và tôi bước đi trên thế gian, chứng kiến, rồi ghi nhớ và lãng quên.\nHôm nay là ngày sinh của bạn, là một trang tình cờ nhặt được trong những Mảnh Vỡ Ký Ức tản mát của bạn. Vì vậy, xin dâng lên tiếng thở dài và Lời chúc.\nKhi thế giới nhớ lại hình dáng hoàn chỉnh của bạn, bạn sẽ cảm thấy thế nào? Hay vẫn chẳng hay biết, chẳng cảm nhận được gì?\nTôi đang đợi Câu trả lời của bạn ở Nơi không tồn tại.\n\n@2"
  },
  Mail_34667_Name = {
    Text = "Ngày sinh…"
  },
  Mail_35231_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Cảm ơn bạn đã ủng hộ và công nhận trò chơi \"Đêm trước khi quên\". Để Người Giữ Gìn có trải nghiệm tốt hơn tại Đại học Misag, chúng tôi chân thành mời bạn điền vào bảng khảo sát trải nghiệm dưới đây. Để cảm ơn sự hợp tác của bạn, chúng tôi đã chuẩn bị phần thưởng là \"bạc tâm\" × 200, hoàn thành bảng khảo sát bạn sẽ nhận được. \n        <SurveyLink:【Nhấp vào đây để điền】>\n        Chúng tôi sẽ lắng nghe nghiêm túc mọi ý kiến của từng Người Giữ Gìn, phản hồi của bạn chắc chắn sẽ giúp Đại học Misag ngày càng tốt hơn! \n        ——Nguyện chìa khóa bạc soi sáng con đường của bạn."
  },
  Mail_35231_Name = {
    Text = "Phiếu khảo sát trải nghiệm phiên bản V1.1"
  },
  Mail_35231_Sender = {
