  Mail_36865_Desc = {
    Text = "Kính thưa Người Giữ Gìn:\n        Trong bản cập nhật V1.2.4, chúng tôi đã điều chỉnh phần thưởng của Thử thách hàng tuần trong \"Giấc mơ thám hiểm\", không còn cung cấp phần thưởng \"hạt ngọc tan rã\"\"kết tinh mô phỏng\" và\"quyền vàng hồng\" nữa. Dựa trên nguyên tắc công bằng, đối với những Người Giữ Gìn đã mở khóa \"Giấc mơ thám hiểm\" trước khi cập nhật, nhưng chưa nhận hết phần thưởng thử thách tuần này và đã đăng nhập trò chơi trước 5:00 ngày 11 tháng 3, chúng tôi sẽ bù đắp phần thưởng \"hạt ngọc tan rã\"\"kết tinh mô phỏng\" và\"quyền vàng hồng\" chưa nhận trong thử thách tuần này. Vui lòng kiểm tra."
  },
  Mail_36865_Name = {
    Text = "V1.2.4 điều chỉnh phần thưởng và bồi thường hàng tuần"
  },
  Mail_36865_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_36866_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Trong bản cập nhật V1.2.4, khi hoàn thành chế độ bình thường của các chương \"Máu và Cát\", \"Lõi Biến Dạng\", \"Nguyện Vọng của Hiệp Sĩ\" trong duy thức tiềm hành, sẽ có thêm các lệnh khóa mới được mở khóa: \"Máu và Cát Gầm Rống\", \"Sự Vĩnh Cửu Ngắn Ngủi\", \"Lời Thề Cuối Cùng\". Đối với những Người Giữ Gìn đã hoàn thành các chương ở chế độ bình thường trước bản cập nhật, chúng tôi sẽ bổ sung các lệnh khóa tương ứng. Vui lòng kiểm tra."
  },
  Mail_36866_Name = {
    Text = "V1.2.4 Duy Thức Tiềm Hành Lệnh Khóa Phát Lại"
  },
  Mail_36866_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_36867_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Trong bản cập nhật V1.2.4, số lượng vật liệu nâng cấp kỹ năng độc đáo và Tinh Thể Mô Phỏng từ 「Sự Tồn Tại Siêu Phàm」 đã được tăng lên. Theo nguyên tắc công bằng, đối với những Người Giữ Gìn đã nhận phần thưởng 「Sự Tồn Tại Siêu Phàm」 của tuần này trước khi cập nhật, chúng tôi sẽ bù đắp số Tinh Thể Mô Phỏng tương đương với giá trị gia tăng của tỷ lệ rơi, dựa trên cấp độ đề xuất của phần thưởng đã nhận. Vui lòng kiểm tra."
  },
  Mail_36867_Name = {
    Text = "V1.2.4 bồi thường điều chỉnh phần thưởng thực thể siêu việt"
