  Mail_36871_Desc = {
    Text = "Kính gửi Người Giữ Gìn:\n\nDựa trên độ khó cao nhất mà bạn đã hoàn thành trong Giấc mơ thám hiểm hôm qua, bạn sẽ nhận được các phần thưởng sau, vui lòng kiểm tra."
  },
