  Mail_44690_Desc = {
    Text = "Xin chào, Người Giữ Gìn: \nBạn đã thực hiện nhiệm vụ trong Giấc mơ thám hiểm hôm qua, với danh hiệu điều tra là \"{s1}\", dưới đây là phần thưởng xếp hạng, Người Giữ Gìn vui lòng kiểm tra."
