  Mail_47307_Desc = {
    Text = "Kính thưa Người Giữ Gìn: \nTrong cuộc thám hiểm giấc mơ hôm qua, bạn đã đạt được danh hiệu \"{s1}\". \nTrong ván đấu pha đối đầu hôm qua, bạn đã đạt được danh hiệu \"{s2}\" và có trận thắng. \nDựa trên kết quả của các thử thách trên, bạn sẽ nhận được các phần thưởng bổ sung sau, hãy nhớ kiểm tra."
