  },
  Mail_47308_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_48005_Desc = {
    Text = "Thân gửi Người Giữ Gìn:\n\nMạo muội làm phiền, hy vọng nét chữ tồi của tôi không làm hỏng tâm trạng tốt của ngài, tôi thực sự không giỏi viết lách…\nViết thư này là để thông báo với ngài rằng, có vẻ như sinh nhật của tôi đã đến. Vì vậy, tôi đã làm một ít bánh quy nhỏ, hy vọng ngài cũng sẽ nếm thử.\nThành thật mà nói, tôi không chắc ngày này có chính xác hay không. Sau khi bị rỗng rỗng, những dấu vết về sự tồn tại của tôi đang dần biến mất. Cô Đóa từng hỏi tôi, cảm giác thế nào khi tỉnh táo nhìn mình bị mọi người lãng quên?\nĐiều đó rất khó diễn tả… giống như đứng trong bóng tối, bên bờ một dòng sông phát sáng, mọi người đều ở bên kia sông trò chuyện với nhau, bận rộn và vội vã đi qua trước mặt tôi. Tôi chỉ có thể nhìn họ, nhưng không thể phát ra bất kỳ âm thanh nào.\nĐó là một cảm giác rất cô đơn. May mắn thay, những người đó không bao gồm ngài.\nÍt nhất ngài vẫn còn nhớ câu chuyện của tôi, phải không?\n\nNgoài ra, mười hai chiếc bánh quy nhỏ đã được gửi kèm theo thư.\n\nMason"
  },
  Mail_48005_Name = {
    Text = "Mạo muội quấy rầy"
  },
  Mail_48005_Sender = {Text = "24"},
  Mail_48145_Desc = {
