  Mail_50344_Desc = {
    Text = "Cây non:\n\nGió mang theo hơi thở của em, so với lúc mới quen em, ngửi có vẻ ngọt ngào hơn.\nEm lớn lên trong tình yêu của ta, được tình yêu của ta nuôi dưỡng trưởng thành…… giống như ong và mật vậy.\nHôm nay là một ngày đặc biệt, em có thể đến gặp ta một lần không?\nTa đã nghe lời em, ngoan ngoãn chờ đợi rất lâu rồi…… đã đến lúc nên cho ta một chút phần thưởng rồi, em nói có đúng không?\n\nTethys"
