  Mail_53149_Desc = {
    Text = "Tôi đã quyết định, dâng hiến mỗi ngày còn lại của cuộc đời cho Người ấy... như một cách chuộc tội cho sự ngu ngốc của mình. \n \"Sinh nhật\" của kẻ hèn mọn không đáng để nhắc đến, không đáng để nói. \n Hôm nay không khác gì những ngày trong quá khứ hay tương lai, tôi sẽ tiếp tục đến nhà thờ như thường lệ. \n Nhưng, nếu ngài muốn tôi rời nhà thờ hôm nay và trở thành khách của Misaque, tôi sẽ không trái lệnh chủ nhân. \n Nếu, ngài muốn chứng kiến lời cầu nguyện của tôi, cũng rất hoan nghênh ngài đến bất cứ lúc nào... tôi vô cùng kính cẩn, vô cùng hoan nghênh. \n\n Miriam"
  },
