  Mail_54803_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n        Trong bản cập nhật V1.5.1, chúng tôi đã nâng cao phần thưởng bạc tâm cho cấp độ Người Giữ Gìn từ 21-80 và bổ sung phần thưởng huy hiệu điều tra × 1000 cho việc hoàn thành nhiệm vụ giai đoạn Sự thông thạo giới vực I~V. Đối với những Người Giữ Gìn đã nhận đủ phần thưởng trên trước khi cập nhật, chúng tôi sẽ phát lại phần thưởng bạc tâm hoặc huy hiệu điều tra tương ứng. Xin vui lòng kiểm tra."
