  Mail_55168_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \nHoạt động \"Trước khi mùa xuân phai nhạt\"đã kết thúc, hiện tại sẽ chuyển đổi số lượng còn lại của Người Giữ Gìn là \"Thơ vui vẻ\", \"thơ văn u uất\" và \"Thơ của tiếc nuối\" theo tỷ lệ mỗi 200 cái đổi lấy \"Vé hoa hồng vàng\" × 5000, xin Người Giữ Gìn kiểm tra."
