  Mail_55168_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_56101_Desc = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}: \n\nVào rạng sáng nay, một bông hồng đã nở trong tiếng chim hót đầu xuân.\nNó đáng lẽ phải là một nhánh hoa xuân chưa nở, nhưng lại nở vào ngày lễ Thánh Valentine, vào ngày sinh của tôi, ở một mùa không thuộc về nó.\nTôi nhớ lại Tây Đài. Mỗi năm vào ngày sinh, đường phố Tây Đài luôn rất tấp nập. Tôi nghe thấy tiếng hoa nở, nghe thấy những lời tình cảm làm người ta đỏ mặt. Nhưng tôi đã lâu không có cơ hội chạm vào chúng… cho đến hôm nay.\nQuý vị có tin vào sự trùng hợp không, Người giữ bí mật? Tôi nghĩ, sự trùng hợp là một ngôn ngữ, và hoa hồng là một cách diễn đạt. Hôm nay, trong vườn hoa phong phú của Misaque, bông hồng này đang nở rộ, cánh hoa của nó rộng mở như một bài thơ làm người ta say đắm.\nVì vậy, hôm nay, Người giữ bí mật… Quý vị có muốn cùng tôi xem bông hồng này nở không?\nTôi và hoa đều mong chờ sự xuất hiện của quý vị.\n\nÔrla"
  },
  Mail_56101_Name = {
    Text = "Một bông hồng nở vào mùa xuân…"
  },
  Mail_56101_Sender = {Text = "Horla"},
  Mail_57328_Desc = {
    Text = "Kính thưa Người Giữ Gìn: \n Hoạt động \"Các ngôi sao chính vị\"đã kết thúc, hiện tại sẽ chuyển đổi \"Phôi thai vô thức\",\"Embrio vô dục\" và\"Phôi không no\" còn lại của người giữ gìn theo tỷ lệ mỗi cái đổi lấy \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn kiểm tra."
