  Mail_74020_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n Hoạt động \"Các ngôi sao chính vị·tái hiện\"đã kết thúc, hiện tại sẽ chuyển đổi số lượng \"Phôi thai vô thức\",\"Embrio vô dục\" và\"Phôi không no\" của Người Giữ Gìn theo tỷ lệ mỗi cái đổi được \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn kiểm tra."
