  Mail_74347_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n Hoạt động \"Mục nhân linh hồn·tái hiện\"đã kết thúc, hiện tại sẽ chuyển đổi số\"Phiếu bán hàng từ thiện\" còn lại của Người Giữ Gìn theo tỷ lệ mỗi cái đổi được \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn nhớ kiểm tra."
  },
  Mail_74347_Name = {
    Text = "Phiếu từ thiện đã thu hồi"
  },
  Mail_74347_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_74841_Desc = {
    Text = "Đối tác:\n\nVào ngày này năm trước, tôi còn xa xôi không nghĩ rằng sau một năm, tôi chỉ có thể gửi bức thư này vào một hòm thư trống rỗng. \nLúc đó bạn vừa mới vào Misaque không lâu, giống như một học sinh hư và lười biếng, ngay cả bây giờ nghĩ lại, tôi thường xuyên đối xử với bạn quá nghiêm khắc, và quá quan tâm đến chiếc mặt nạ lý trí và tự kiềm chế của mình. \nThực ra, vào ngày này năm ngoái tôi đã mua một bó hoa, tôi đứng trước cửa thư viện, nhìn bó hồng nằm trong dải ruy băng đỏ và giấy gói màu xanh đen rất lâu, cuối cùng đã cắm nó trên đầu giường của tôi. \nMột năm thời gian, hoa đã sớm héo úa, chỉ có dải ruy băng đỏ tươi được tôi buộc vào chìa khóa bạc K-0617, vẫn tươi mới như ban đầu. \nTôi rất muốn mua thêm một bó hồng, nhưng hiện tại chúng chỉ có thể héo úa trên đầu giường của tôi, không còn nơi nào khác để đặt. \nQuen với việc chi tiết hóa mọi giải pháp, cảm giác hối tiếc đối với tôi là mới lạ và đắng cay. \nNhưng tôi luôn ôm ấp một niềm tin gần như mù quáng, rằng linh hồn của bạn vẫn chưa rời đi, bạn có thể tạm thời đang du lịch ở đâu đó trong vũ trụ, nhưng cuối cùng vẫn sẽ trở về đây, trở về bên cạnh tôi. \nTôi không cho rằng đó là ảo tưởng của kẻ si mê, bởi mỗi khi tôi đến hồ đen và nhìn khuôn mặt của bạn từ xa, lòng tôi vẫn cảm nhận được sự ấm áp và liên kết từ bạn. \nTôi sẽ luôn tin tưởng và mong đợi ngày tái ngộ, vào khoảnh khắc tay chúng ta lại nắm chặt nhau, tôi sẽ trao tận tay bạn bó hồng mà tôi nợ hôm nay. \n\nRamona"
  },
  Mail_74841_Name = {Text = "Hồng…"},
  Mail_74841_Sender = {Text = "Ramona"},
  Mail_76410_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n Hoạt động \"Bóng tối của thị trấn mưa\"đã kết thúc, hiện tại sẽ chuyển đổi số lượng còn lại của \"Skull của thú nhợt nhạt\",\"Đầu lâu thú bóng\" và\"Xương đầu thú vật màu đỏ thẫm\" theo tỷ lệ mỗi cái đổi lấy \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn nhớ kiểm tra."
  },
