  },
  Mail_79646_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n Hoạt động「Chôn sâu trong ký ức」đã kết thúc, hiện tại sẽ chuyển đổi báo cáo chẩn đoán còn lại của Người Giữ Gìn theo tỷ lệ mỗi lần đổi「Vé hoa hồng vàng」× 40, xin Người Giữ Gìn nhớ kiểm tra."
  },
  Mail_79646_Name = {
    Text = "Chôn dưới ký ức thu hồi tiền tệ"
  },
  Mail_79646_Sender = {
    Text = "Hội đồng Misaque"
  },
  Mail_80091_Desc = {
    Text = "Người giữ gìn:\n\nKhi bạn mở bức thư này, điều đó có nghĩa là tín hiệu tôi đã chôn sâu trong lòng bạn đã có hiệu lực.\nHaha, đừng lo lắng. Đây chỉ là một thao tác thôi để đảm bảo bữa tiệc sinh nhật của tôi diễn ra suôn sẻ, một sự thôi miên không đáng kể không gây ảnh hưởng gì đến bạn.\nTiếp theo, bạn sẽ cảm thấy một ham muốn mãnh liệt muốn đi mua sắm, hãy thuận theo nó mà đến đường phố, từ những cửa sổ rực rỡ hãy chọn một món quà mà bạn thích nhất, sau đó đưa cho tôi.\nTôi biết bạn đang nghi ngờ vào lúc này và công nhận tính hợp lý của nó, nhưng người sinh nhật luôn có một vài đặc quyền phải không? Tôi làm như vậy chỉ vì sợ bạn quên mất ngày đặc biệt này. Dù sao, bạn cũng là vị khách mà tôi luôn mong đợi.\nCuối cùng, tôi sẽ kiên nhẫn chờ đợi sự đến thăm của bạn — đừng quên món quà.\n\nClementine"
  },
  Mail_80091_Name = {
    Text = "“Quà” được chọn “trực tiếp”"
  },
  Mail_80091_Sender = {Text = "Clementine"},
  Mail_81288_Desc = {
    Text = "Kính gửi Người Giữ Gìn: \n Cảm ơn bạn đã ủng hộ và công nhận \"Đêm trước khi quên\". Để Người Giữ Gìn có trải nghiệm chơi game tốt hơn tại Đại học Misag, chúng tôi chân thành mời bạn điền vào bảng khảo sát trải nghiệm dưới đây. Để cảm ơn sự phối hợp của bạn, chúng tôi chuẩn bị phần thưởng \"bạc tâm\" × 200, hoàn thành bảng khảo sát bạn sẽ nhận được. Thời gian kết thúc khảo sát là 9:00 ngày 14 tháng 4, xin lưu ý điền đúng thời gian. \n <SurveyLink:【Nhấp vào đây để điền】>\n Chúng tôi sẽ lắng nghe nghiêm túc ý kiến của từng Người Giữ Gìn, phản hồi của bạn chắc chắn sẽ giúp Đại học Misag ngày càng phát triển! \n —— Nguyện chìa khóa bạc soi sáng con đường của bạn."
  },
  Mail_81288_Name = {
    Text = "Bảng điều tra trải nghiệm phiên bản V2.2.0"
  },
  Mail_81288_Sender = {
    Text = "Phòng Quản Lý Misaque"
  },
  Mail_81326_Desc = {
    Text = "Người ân nhân:\n\nHôm nay đối với tôi và Polykus là ngày lễ duy nhất trong năm. Khi ở trong nhà thờ, chúng tôi không được phép tập trung quá nhiều vào ý nghĩa của bản thân, mà toàn bộ giá trị của chúng tôi chỉ tồn tại trong công việc phục vụ các người giữ đèn, trong đức tin như vậy, bất kỳ lễ hội nào khác cũng đều là những ảo tưởng vô nghĩa.\nNhưng khi đến ngày sinh nhật, tôi và Polykus vẫn lén lút ăn mừng, chúng tôi chuẩn bị một món quà nhỏ nhất có thể cho nhau trong bí mật, và ngóng trông ngày này đến gần.\nKhoảng thời gian ăn mừng sinh nhật thường diễn ra vào ban đêm - đó là thời gian tự do duy nhất của chúng tôi trong một ngày, đôi bàn tay khéo léo và ý tưởng của Polykus luôn khiến quà của anh vượt qua món quà của tôi, có lần anh thậm chí đã dùng những chiếc lông vũ rơi để dệt lên một bông hoa nở rộ.\nThực ra tôi không giỏi trong việc chuẩn bị bất ngờ, Polykus luôn nói biểu hiện thường ngày của tôi đã bán đứng tất cả, và những gì tôi có dường như thật nghèo nàn và chán chường trong mắt quý vị, nhưng hôm nay tôi đã nghĩ ra một cách tuyệt vời để chia sẻ niềm vui với quý vị.\nKhi quý vị nghe thấy cửa sổ bị gõ ba lần vào ban đêm, xin đừng sợ hãi, hãy mở cửa sổ, tôi sẽ đưa quý vị đi trải nghiệm cảm giác của tầng mây và làn gió đêm.\n\nCastor"
  },
  Mail_81326_Name = {
    Text = "Đêm lang thang..."
  },
  Mail_81326_Sender = {Text = "Castor"},
  Mail_84142_Desc = {
    Text = "Người giữ gìn:\n\nTrước khi hội tụ, tôi đã viết bức thư này, chính thức mời và giới thiệu với bạn về \"Chuyến hành trình sinh nhật\" của tôi.\nĐiểm dừng chân đầu tiên của chuyến hành trình này là sông Thames. Chúng tôi sẽ lên chiếc thuyền hàng đã được cải tạo thành nhà hàng di động, vừa đi dạo trên sông vừa thưởng thức dứa ngâm trong hộp và rượu rum. Đây là món ngon chỉ được phục vụ vào sinh nhật của thủy thủ, hy vọng bạn sẽ thích.\nĐiểm dừng chân thứ hai là đài quan sát cảng. Xin yên tâm, tôi đã xin phép Hiệp hội Khinh khí cầu để quan sát. Khi khinh khí cầu bay lên cao, nhìn xuống toàn bộ hành trình London, chúng ta sẽ cùng nhau cắt bánh, như một buổi lễ kỷ niệm.\nTrước đây, điều kiện hành trình rất hạn chế, chiếc bánh sinh nhật chỉ là mô hình được thợ mộc làm từ gỗ sồi và caramel, vì vậy tôi cũng không biết vị của bánh như thế nào, lần này được cùng bạn thưởng thức, tôi nghĩ ngoài vẻ đẹp của thức ăn, tôi cũng sẽ thu được nhiều điều hơn.\nĐiểm dừng chân thứ ba, hoặc có lẽ nên gọi là phần thứ ba, là bản đồ sao tùy chỉnh. Tôi đã đánh dấu vị trí thiên thể vào thời điểm tôi ra đời trên bản đồ hải lý, nếu bạn không phiền, tôi muốn đánh dấu vị trí của bạn vào đó, bản đồ sao hàng hải độc nhất này sẽ là món quà quý giá nhất để giữ gìn.\nThực ra, khi viết bức thư này, tôi đã có chút do dự. Những hành động này rõ ràng vượt ngoài ranh giới thông thường, nhưng hôm nay là ngày đặc biệt, bạn đối với tôi cũng là người đặc biệt, xứng đáng để tôi phá vỡ quy tắc.\nVậy nên, xin bạn hãy nhất định đừng từ chối, và đến đúng hẹn.  \nKepsant"
  },
  Mail_84142_Name = {
    Text = "\"Hành trình\" lời mời"
  },
  Mail_84142_Sender = {Text = "Corposant"},
